These PSWFs are defined as the solutions of the following energy maximization problem :
\begin{equation*}
\mbox{ Find } g=\arg\max_{f\in B_c}\frac{\int_{-1}^1|f(t)|^2 dt}{\int_{\mathbb{R}}|f(t)|^2 dt}
\end{equation*}

Where $B_c$ is the classical Paley-Winer space, defined by
\begin{equation} B_c=\{ f\in L^2(\mathbb R),\,\, \mbox{Support } \widehat f\subseteq [-c,c]\}.
\end{equation}

They are defined as the eigenfunctions of the  Gegenbauer perturbed differential operator,
\begin{equation*}
\mathcal L^{(\alpha)}_c \varphi(x)= (1-x^2)\varphi''(x)-2\left(\alpha+1\right)x\varphi'(x) - c^2 x^2 \varphi(x)=
\mathcal L_0 \varphi(x)-c^2 x^2 \varphi(x), \mbox{ where } \alpha>-1; c>0,
\end{equation*}
as well as  the eigenfunctions of the following commuting  weighted finite Fourier transform integral operator,
\begin{equation} {\displaystyle \mathcal F_c^{(\alpha)} f(x)=\int_{-1}^1 e^{icxy}  f(y)\,(1-y^2)^{\alpha}\, dy,\, \alpha > -1.}
\end{equation}

Also, note that  the $(n+1)-$th eigenvalue $\chi_n^{\alpha}(c)$ of $\mathcal L_c^{(\alpha)}$ satisfies the following classical inequalities,
\begin{equation} n (n+2\alpha+1) \leq \chi_n^{\alpha}(c) \leq n (n+2\alpha+1) +c^2,\quad \forall n\geq 0.
\end{equation}

Here, $\widetilde P^{(\alpha,\alpha)}_k$ denotes the normalized Jacobi polynomial of degree $k,$ given by
\begin{equation} \widetilde P^{(\alpha,\alpha)}_{k}(x)= \frac{1}{\sqrt{h_k}}P^{(\alpha,\alpha)}_k(x),\quad h_k=\frac{2^{2\alpha+1}\Gamma^2(k+\alpha+1)}{k!(2k+2\alpha+1)\Gamma(k+2\alpha+1)}.
\end{equation}

We first recall the Courant-Fischer-Weyl Min-Max variational principle concerning the eigenvalues of a compact self-adjoint operator $T$ on a Hilbert space $\mathcal G,$ with positive eigenvalues arranged in the decreasing order $\lambda_0\geq \lambda_1\geq \cdots\geq \lambda_n\geq \cdots ,$ then we have $$\lambda_n = \min_{f\in S_n}\,\,\, \max_{f\in S_n^{\perp},\|f\|_{\mathcal G}=1} < Tf, f>_{\mathcal G},$$ where $S_n$ is a subspace of $\mathcal G$ of dimension $n.$ In our case, we have $T=\mathcal F_c^{\alpha^*}\mathcal F_c^{(\alpha)},$ $\mathcal G= L^2(I,\omega_{\alpha}).$ We consider the special case of $$S_n=\mbox{Span}\left\{\widetilde P^{(\alpha,\alpha)}_0, \widetilde P^{(\alpha,\alpha)}_1,\ldots,\widetilde P^{(\alpha,\alpha)}_{n-1}ight\}$$ and $$f=\displaystyle\sum_{k\geq n} a_k \widetilde P^{(\alpha,\alpha)}_k \in S_n^{\perp},\qquad \parallel f\parallel_{L^2_{(I,\omega_\alpha)}}=\displaystyle\sum_{k\geq n}|a_k|^2=1.$$ Here the $ \widetilde P^{(\alpha,\alpha)}_{k} $ are the normalized Jacobi polynomials given by \eqref{JacobiP}. From [\cite{NIST} page 456], we have  egin{equation} \| \mathcal F_c^{(\alpha)} P^{(\alpha,\alpha)}_k\|_{L^2(I,\omega_{\alpha})} = \parallel \sqrt{\pi} \left( rac{2}{cx}ight) ^{\alpha+1/2}  rac{\Gamma(k+\alpha+1)}{\Gamma(k+1)}J_{k+\alpha+1/2}(cx) \parallel_{L^2(I,\omega_{\alpha})}. \end{equation} and  egin{equation} \parallel x^k \parallel_{L^2(I,\omega_{\alpha})}^2= eta(k+1/2,\alpha+1)\leq \sqrt{ rac{\pi}{e}} rac{\Gamma(\alpha+1)}{k^{\alpha+1}}. \end{equation} By using the well-known bound of the Bessel function given by  egin{equation} |J_{\alpha}(x)|\leq  rac{|x|^{\alpha}}{2^{\alpha}\Gamma(\alpha+1)}\;\;\;\;\;\;\;\; orall\alpha>-1/2, \;\;  orall x \in \mathbb{R}, \end{equation} one gets,  egin{eqnarray} \| \mathcal F_c^{(\alpha)} \widetilde P^{(\alpha,\alpha)}_k\|_{L^2(I,\omega_{\alpha})} &\leq &  rac{\sqrt{\pi}\Gamma(k+\alpha+1)}{\sqrt{h_k}\Gamma(k+1)\Gamma(k+\alpha+3/2)}\left( rac{c}{2}ight) ^{k} \parallel x^k \parallel_{L^2(I,\omega_{\alpha})}. 
onumber\ &\leq &  rac{\sqrt{\pi}\Gamma(k+\alpha+1)}{\sqrt{h_k}\Gamma(k+1)\Gamma(k+\alpha+3/2)}\left( rac{c}{2}ight) ^{k}\left( rac{\pi}{e}ight)^{1/4} rac{\sqrt{\Gamma(\alpha+1)}}{k^{ rac{\alpha+1}{2}}} \end{eqnarray} Next, we use \eqref{JacobiP} and the following useful inequalities for the Gamma function, see \cite{Batir}  egin{equation} \sqrt{2e}\left( rac{x+1/2}{e}ight)^{x+1/2}\leq\Gamma(x+1)\leq \sqrt{2\pi}\left( rac{x+1/2}{e}ight)^{x+1/2}\;,\;\;\; x>0. \end{equation} Then, we have  egin{eqnarray} \| \mathcal F_c^{(\alpha)} \widetilde P^{(\alpha,\alpha)}_k\|_{L^2(I,\omega_{\alpha})} &\leq &  rac{\sqrt{\pi}\sqrt{(k+\alpha+ rac{1}{2})\Gamma(k+2\alpha+1)}}{2^{\alpha+ rac{1}{2}}\sqrt{\Gamma(k+1)}\Gamma(k+\alpha+ rac{3}{2})}\left( rac{c}{2}ight) ^{k}\left( rac{\pi}{e}ight)^{ rac{1}{4}} rac{\sqrt{\Gamma(\alpha+1)}}{k^{ rac{\alpha+1}{2}}}
onumber\ &=& rac{\pi \sqrt{\Gamma(\alpha+1)} ig(k+2\alpha+ rac{1}{2}\Big)^{ rac{k}{2}+\alpha+ rac{1}{4 }}}{\sqrt{ec}2^{\alpha}k^{ rac{\alpha+1}{2}}\left(k+ rac{1}{2}ight)^{ rac{k}{2}+ rac{1}{4}}\left(k+\alpha+1ight)^{k+\alpha+ rac{1}{2}}} \left( rac{ce}{2}ight) ^{k+ rac{1}{2 }}
onumber\ &=& rac{\pi \sqrt{\Gamma(\alpha+1)}}{\sqrt{ec}2^{\alpha}k^{ rac{\alpha+1}{2}}}\left(1+ rac{\alpha- rac{1}{2}}{k+\alpha+1}ight)^{ rac{k}{2}+\alpha+ rac{1}{4}} \left( rac{ce}{2k+1}ight) ^{k+ rac{1}{2}}. \end{eqnarray} Since the function $g_a(x)=\left(1+ rac{a}{x}ight)^{a+x}$ for $x\geq1$ and $a>-1$ is decreasing on $[1,+\infty[$. Then, we have  egin{eqnarray} \| \mathcal F_c^{(\alpha)} \widetilde P^{(\alpha,\alpha)}_k\|_{L^2(I,\omega_{\alpha})} &\leq & rac{\pi \sqrt{\Gamma(\alpha+1)}}{\sqrt{c}k^{ rac{\alpha+1}{2}}} \left( rac{ce}{2k+1}ight) ^{k+ rac{1}{2}}. \end{eqnarray} Hence, For the previous $f\in S_n^{\perp},$ and by using H"older's inequality, combined with the Minkowski's inequality for an infinite sums, and taking into account that $\|f\|_{L^2(I,\omega_{\alpha})}= 1,$ so that $|a_k|\leq 1,$ for $k\geq n,$ one gets:  egin{eqnarray} |< \mathcal F_c^{\alpha^*}\mathcal F_c^{(\alpha)} f,f>_{L^2(I,\omega_{\alpha})}|&=&|< \mathcal F_c^{(\alpha)} f,\mathcal F_c^{(\alpha)}f>_{L^2(I,\omega_{\alpha})}| \leq \sum_{k\geq n} |a_k|^2 \| \mathcal F_c^{(\alpha)} \widetilde P^{(\alpha,\alpha)}_k\|^2_{L^2(I,\omega_{\alpha})}\ &\leq&\left( rac{2^ rac{1}{4}\pi \sqrt{\Gamma(\alpha+1)}}{\sqrt{ec}} \sum_{k\geq n} \left( rac{ec}{2k+1}ight)^{k+1/2} rac{1}{k^{ rac{\alpha+1}{2}}}ight)^2 \end{eqnarray} The decay of the sequence appearing in the previous sum, allows us to compare this later with its integral counterpart, that is  egin{equation} \sum_{k\geq n} \left( rac{ec}{2k+1}ight)^{k+1/2} rac{1}{k^{ rac{\alpha+1}{2}}} \leq \int_{n-1}^{\infty} rac{ e^{-(x+1/2) \log( rac{2x+1}{ec})}}{x^{ rac{\alpha+1}{2}}}\, dx\leq \int_{n-1}^{\infty} rac{ e^{-(x+1/2)\log( rac{2n-1}{ec})}}{(n-1)^{ rac{\alpha+1}{2}}}\, dx. \end{equation} Hence, by using (ef{Eq3.3}) and (ef{Eq3.4}), one concludes that  egin{eqnarray} \max_{f\in S_n^{\perp},\, \|f\|_{L^2(I,\omega_{\alpha})=1}} < \mathcal F_c^{(\alpha)} f, \mathcal F_c^{(\alpha)} f>^{1/2}_{L^2(I,\omega_{\alpha})}&\leq & rac{2^ rac{1}{4}\pi \sqrt{\Gamma(\alpha+1)}}{\sqrt{ec}}  rac{1}{\log( rac{2n-1}{ec})} \left( rac{ec}{2n-1}ight)^{n-1/2} rac{1}{(n-1)^{ rac{\alpha+1}{2}}}
onumber\ &\leq&\pi \sqrt{\Gamma(\alpha+1)} \left( rac{2}{ec}ight)^{ rac{\alpha+2}{2}}  rac{1}{\log( rac{2n-1}{ec})} \left( rac{ec}{2n-1}ight)^{n+ rac{\alpha}{2}} \end{eqnarray} To conclude the proof of the theorem, it suffices to use the Courant-Fischer-Weyl Min-Max variational principle.$\qquad \Box $

By using the well-known  bound of the Bessel function given by
\begin{equation} |J_{\alpha}(x)|\leq \frac{|x|^{\alpha}}{2^{\alpha}\Gamma(\alpha+1)}\;\;\;\;\;\;\;\;\forall\alpha>-1/2, \;\; \forall x \in \mathbb{R},
\end{equation}
one gets,
\begin{eqnarray}

\| \mathcal F_c^{(\alpha)} \widetilde P^{(\alpha,\alpha)}_k\|_{L^2(I,\omega_{\alpha})}
&\leq & \frac{\sqrt{\pi}\Gamma(k+\alpha+1)}{\sqrt{h_k}\Gamma(k+1)\Gamma(k+\alpha+3/2)}\left(\frac{c}{2}\right) ^{k} \parallel  x^k
\parallel_{L^2(I,\omega_{\alpha})}. \nonumber\\
&\leq & \frac{\sqrt{\pi}\Gamma(k+\alpha+1)}{\sqrt{h_k}\Gamma(k+1)\Gamma(k+\alpha+3/2)}\left(\frac{c}{2}\right) ^{k}\left(\frac{\pi}{e}\right)^{1/4}\frac{\sqrt{\Gamma(\alpha+1)}}{k^{\frac{\alpha+1}{2}}}
\end{eqnarray}

Next, we use \eqref{JacobiP} and the following useful inequalities for the Gamma function, see  \cite{Batir}
\begin{equation} \sqrt{2e}\left(\frac{x+1/2}{e}\right)^{x+1/2}\leq\Gamma(x+1)\leq \sqrt{2\pi}\left(\frac{x+1/2}{e}\right)^{x+1/2}\;,\;\;\; x>0.
\end{equation}
Then, we have
\begin{eqnarray}

\| \mathcal F_c^{(\alpha)} \widetilde P^{(\alpha,\alpha)}_k\|_{L^2(I,\omega_{\alpha})} &\leq & \frac{\sqrt{\pi}\sqrt{(k+\alpha+\frac{1}{2})\Gamma(k+2\alpha+1)}}{2^{\alpha+\frac{1}{2}}\sqrt{\Gamma(k+1)}\Gamma(k+\alpha+\frac{3}{2})}\left(\frac{c}{2}\right) ^{k}\left(\frac{\pi}{e}\right)^{\frac{1}{4}}\frac{\sqrt{\Gamma(\alpha+1)}}{k^{\frac{\alpha+1}{2}}}\nonumber\\
&=&\frac{\pi \sqrt{\Gamma(\alpha+1)}\big(k+2\alpha+\frac{1}{2}\Big)^{\frac{k}{2}+\alpha+\frac{1}{4
}}}{\sqrt{ec}2^{\alpha}k^{\frac{\alpha+1}{2}}\left(k+\frac{1}{2}\right)^{\frac{k}{2}+\frac{1}{4}}\left(k+\alpha+1\right)^{k+\alpha+\frac{1}{2}}}
\left(\frac{ce}{2}\right) ^{k+\frac{1}{2
}}\nonumber\\
&=&\frac{\pi \sqrt{\Gamma(\alpha+1)}}{\sqrt{ec}2^{\alpha}k^{\frac{\alpha+1}{2}}}\left(1+\frac{\alpha-\frac{1}{2}}{k+\alpha+1}\right)^{\frac{k}{2}+\alpha+\frac{1}{4}}
\left(\frac{ce}{2k+1}\right) ^{k+\frac{1}{2}}.
\end{eqnarray}

Since the function $g_a(x)=\left(1+\frac{a}{x}\right)^{a+x}$ for
$x\geq1$ and $a>-1$ is decreasing on $[1,+\infty[$. Then, we have
\begin{eqnarray}

\| \mathcal F_c^{(\alpha)} \widetilde P^{(\alpha,\alpha)}_k\|_{L^2(I,\omega_{\alpha})} &\leq &\frac{\pi \sqrt{\Gamma(\alpha+1)}}{\sqrt{c}k^{\frac{\alpha+1}{2}}}
\left(\frac{ce}{2k+1}\right) ^{k+\frac{1}{2}}. \end{eqnarray}

Hence, For the previous $f\in S_n^{\perp},$  and by using H\"older's inequality, combined with  the Minkowski's inequality for an infinite sums, and taking into account that  $\|f\|_{L^2(I,\omega_{\alpha})}= 1,$ so that $|a_k|\leq 1,$ for $k\geq n,$  one gets:
\begin{eqnarray}

|< \mathcal F_c^{\alpha^*}\mathcal F_c^{(\alpha)} f,f>_{L^2(I,\omega_{\alpha})}|&=&|< \mathcal F_c^{(\alpha)} f,\mathcal F_c^{(\alpha)}f>_{L^2(I,\omega_{\alpha})}| \leq \sum_{k\geq n} |a_k|^2 \| \mathcal F_c^{(\alpha)} \widetilde P^{(\alpha,\alpha)}_k\|^2_{L^2(I,\omega_{\alpha})}\\ &\leq&\left(\frac{2^\frac{1}{4}\pi \sqrt{\Gamma(\alpha+1)}}{\sqrt{ec}} \sum_{k\geq n} \left(\frac{ec}{2k+1}\right)^{k+1/2}\frac{1}{k^{\frac{\alpha+1}{2}}}\right)^2
\end{eqnarray}

The decay of the sequence appearing in the previous sum, allows us to compare this later with its integral counterpart, that is
\begin{equation} \sum_{k\geq n} \left(\frac{ec}{2k+1}\right)^{k+1/2}\frac{1}{k^{\frac{\alpha+1}{2}}}
\leq \int_{n-1}^{\infty}\frac{ e^{-(x+1/2) \log(\frac{2x+1}{ec})}}{x^{\frac{\alpha+1}{2}}}\, dx\leq
\int_{n-1}^{\infty}\frac{ e^{-(x+1/2)\log(\frac{2n-1}{ec})}}{(n-1)^{\frac{\alpha+1}{2}}}\, dx.
\end{equation}

Hence, by using (\ref{Eq3.3}) and (\ref{Eq3.4}), one concludes that
\begin{eqnarray}

\max_{f\in S_n^{\perp},\, \|f\|_{L^2(I,\omega_{\alpha})=1}} < \mathcal F_c^{(\alpha)} f, \mathcal F_c^{(\alpha)} f>^{1/2}_{L^2(I,\omega_{\alpha})}&\leq &\frac{2^\frac{1}{4}\pi \sqrt{\Gamma(\alpha+1)}}{\sqrt{ec}} \frac{1}{\log(\frac{2n-1}{ec})} \left(\frac{ec}{2n-1}\right)^{n-1/2}\frac{1}{(n-1)^{\frac{\alpha+1}{2}}}\nonumber\\
&\leq&\pi \sqrt{\Gamma(\alpha+1)} \left(\frac{2}{ec}\right)^{\frac{\alpha+2}{2}} \frac{1}{\log(\frac{2n-1}{ec})} \left(\frac{ec}{2n-1}\right)^{n+\frac{\alpha}{2}} \end{eqnarray}

As it is done in \cite{Bonami-Karoui2}, we consider the incomplete elliptic integral
\begin{equation} S(x)=\int_x^1 \sqrt{\frac{1-qt^2}{1-t^2}}\, dt,\qquad q=\frac{c^2}{\chi_n^\alpha(c)}<1.
\end{equation}

Then, we  write $\psi_{n,c}^{(\alpha)}$ into the form
\begin{equation} \psi(x)=\phi_{\alpha}(x)V(S(x)),\qquad \phi_{\alpha}(x)=(1-x^2)^{(-1-2\alpha)/4} (1-qx^2)^{-1/4}.
\end{equation}

By combining (\ref{eq2_diff}), (\ref{Liouvile_transform2}) and using straightforward computations,
it can be easily checked that $V(\cdot)$ satisfies the following second order differential equation
\begin{equation}
V''(s)+\left(\chi_{n,\alpha}+\theta_{\alpha}(s)\right)V(s)=0,\quad s\in [0, S(0)]
\end{equation}
with $$ \theta_{\alpha}(S(x))=(w_{\alpha}(x)(1-x^2)\phi_{\alpha}'(x))'\frac{1}{\phi_{\alpha}(x)w_{\alpha}(x)(1-qx^2)}.$$

It follows that $\theta_{\alpha}(s)$ can be written as
\begin{equation}
\theta_{\alpha}(S(x))=\frac{1}{16(1-qx^2)}\Big[\Big(\frac{Q_{\alpha}'(x)}{Q_{\alpha}(x)}\Big)^2(1-x^2)-4\frac{d}{dx}\Big((1-x^2)\frac{Q_{\alpha}'(x)}{Q_{\alpha}(x)}\Big)-4(1-x^2)\frac{Q_{\alpha}'(x)}{Q_{\alpha}(x)}
\frac{w_{\alpha}'(x)}{w_{\alpha}(x)}\Big].
\end{equation}

Hence, we have
\begin{eqnarray}
\theta_{\alpha}(S(x)) &=&\theta_0(S(x))+\frac{-1}{4(1-qx^2)}\Big[ \big(\frac{w_{\alpha}'(x)}{w_{\alpha}(x)}\big)^2 (1-x^2)+2\frac{d}{dx}[(1-x^2)\frac{w_{\alpha}'(x)}{w_{\alpha}(x)}]  \Big] \nonumber \\
&=&\theta_0(S(x))+ \frac{1}{(1-x^2)(1-qx^2)}\Big( -\alpha^2 x^2 + \alpha (1-x^2) \Big) \nonumber \\
&=&\theta_0(S(x))+ \frac{\alpha(1+\alpha)}{(1-qx^2)}-\frac{\alpha^2}{(1-q x^2)(1-x^2)}.
\end{eqnarray}

So one has the inequality
	\begin{equation} K_n(1) - K_n(0) = A^2 \leq 2(2\alpha+1) \int_{0}^{1} t{|\psi_{n,c}^{(\alpha)}(t) |}^2 \omega_{\alpha}(t) dt \leq (2\alpha+1) \Bigg[\int_{-1}^{1}t^2 |\psi_{n,c}^{(\alpha)}(t) |^2 \omega_{\alpha}(t) dt \Bigg] ^{1/2}.
	\end{equation}
	That is
	\begin{equation} A^2 \leq (2\alpha+1) B^{1/2}.
	\end{equation}

Remark that \eqref{estimation} implies that
	\begin{equation} 1-B \leq 2 A^2
	\end{equation}

We recall here the expression of the differential operator $ \mathcal{L}_c^{(\alpha)}$ : $$ \mathcal L_c^{(\alpha)} (f)(x)= - rac{1}{\omega_{\alpha}(x)}  rac{d}{dx}\left[ \omega_{\alpha}(x) (1-x^2) f'(x)ight] +c^2 x^2 f(x) = -(1-x^2)f''(x) + 2(\alpha+1)xf'(x) + c^2x^2f(x) .$$ For any positive integer $r$ and function $ f\in H^r_{\alpha,0}$ , the derivatives of $ \mathcal{L}_c^{(\alpha)}.f$ are given by :  egin{eqnarray}  rac{d^r}{dx^r}[\mathcal{L}_c^{(\alpha)}.f](x) &=& -(1-x^2)  rac{d^{r+2}f}{dx^{r+2}}(x) + 2(r+\alpha+1)x rac{d^{r+1}f}{dx^{r+1}}(x) + \Big[ r(2\alpha + r +1)+c^2 x^2 \Big]  rac{d^{r}f}{dx^{r}}(x) 
onumber \ &+& 2 c^2rx  rac{d^{r-1}f}{dx^{r-1}}(x) + c^2 r(r-1)  rac{d^{r-2}f}{dx^{r-2}}(x) \end{eqnarray} This expression yields directly that :  egin{eqnarray} 
orm{\mathcal{L}_c^{(\alpha)}.f}^2_{\alpha,r} &=& \sum_{m=0}^r 
orm{ rac{d^r}{dx^r}[\mathcal{L}_c^{(\alpha)}.f]}^2_{L^2(I,\omega_\alpha)} 
onumber \ & \leq C & 
orm{f}^2_{\alpha,r+2} \end{eqnarray} Therefore $\mathcal{L}_c^{(\alpha)}$ is a continuous operator from $ H^{r+2}_{\alpha,0}(I)$ into $ H^r_{\alpha,0}(I)$. \ Then, by induction on $ r $, we obtain  egin{equation} 
orm{\Big[\mathcal{L}_c^{(\alpha)}\Big]^r.f}_{\alpha,s} \leq C 
orm{f}_{\alpha,r+2} \end{equation} For $ f \in H^r_{\alpha}(I) $, we write : $$ f = \sum_{n=0}^{\infty} \hat{f_n}\psi^{(\alpha)}_{n,c} \quad \mbox{with} \quad \hat{f_n} = \int_{-1}^1 f(x) \psi^{(\alpha)}_{n,c}(x) \omega_{\alpha}(x) $$ Since $\mathcal{L}_c^{(\alpha)}$ is self adjoint on $L^2(I,\omega_{\alpha}) $,  egin{eqnarray} \hat{f_n} &=&  rac{1}{\chi_{n,\alpha}}\int_{-1}^1 \mathcal{L}_c^{(\alpha)}.\psi_{n,c}^{(\alpha)}(x) f(x) \omega_{\alpha}(x) dx =  rac{1}{\chi_{n,\alpha}}\int_{-1}^1 \mathcal{L}_c^{(\alpha)}.f(x) \psi_{n,c}^{(\alpha)}(x) \omega_{\alpha}(x) dx 
onumber \ &=& ... =  rac{1}{(\chi_{n,\alpha})^r}\int_{-1}^1 \Big[\mathcal{L}_c^{(\alpha)}\Big]^r.f(x) \psi_{n,c}^{(\alpha)}(x) \omega_{\alpha}(x) dx \end{eqnarray} Thus  egin{eqnarray} |\hat{f_n}|^2 &=&  rac{1}{\Big(\chi_{n}^{(\alpha)}\Big)^{2r}}|\Big<\Big[\mathcal{L}_c^{(\alpha)}\Big]^r.f,\psi_{n,c}^{(\alpha)}\Big>_{L^2(I,\omega_{\alpha})}|^2 \leq  rac{1}{\Big(\chi_{n}^{(\alpha)}\Big)^{2r}} 
orm{\Big[\mathcal{L}_c^{(\alpha)}\Big]^rf}_{L^2(I,\omega_{\alpha})} 
onumber \ &\leq &  rac{C}{\Big(\chi_{n}^{(\alpha)}\Big)^{2r}} 
orm{f}^2_{r+2,\alpha} \end{eqnarray} By writing $ 
orm{f-S_Nf}^2_{L^2(I,\omega_\alpha)} = \displaystyle \sum_{n=N+1}^{\infty} |\hat{f_n}|^2 $ one gets \eqref{approx1} Then, we obtain the result for $u$ regular, then for $ u \in H^{r+2}_{\alpha} (I)$ by density and continuity. Finally, for $s$ between two even integers, we conclude by interpolation.

For any positive integer $r$ and function $ f\in H^r_{\alpha,0}$ , the derivatives of $ \mathcal{L}_c^{(\alpha)}.f$ are given by :

\begin{eqnarray}
\frac{d^r}{dx^r}[\mathcal{L}_c^{(\alpha)}.f](x) &=& -(1-x^2) \frac{d^{r+2}f}{dx^{r+2}}(x) + 2(r+\alpha+1)x\frac{d^{r+1}f}{dx^{r+1}}(x) + \Big[ r(2\alpha + r +1)+c^2 x^2 \Big] \frac{d^{r}f}{dx^{r}}(x) \nonumber \\
&+& 2 c^2rx \frac{d^{r-1}f}{dx^{r-1}}(x) + c^2  r(r-1) \frac{d^{r-2}f}{dx^{r-2}}(x)
\end{eqnarray}
This expression yields directly that :
\begin{eqnarray}
\norm{\mathcal{L}_c^{(\alpha)}.f}^2_{\alpha,r} &=& \sum_{m=0}^r \norm{\frac{d^r}{dx^r}[\mathcal{L}_c^{(\alpha)}.f]}^2_{L^2(I,\omega_\alpha)} \nonumber \\
& \leq C & \norm{f}^2_{\alpha,r+2}
\end{eqnarray}
Therefore $\mathcal{L}_c^{(\alpha)}$ is a continuous operator from $ H^{r+2}_{\alpha,0}(I)$ into $ H^r_{\alpha,0}(I)$. \\

Then, by induction on $ r $, we obtain
\begin{equation}
\norm{\Big[\mathcal{L}_c^{(\alpha)}\Big]^r.f}_{\alpha,s} \leq C \norm{f}_{\alpha,r+2}
\end{equation}

Since $\mathcal{L}_c^{(\alpha)}$ is self adjoint on $L^2(I,\omega_{\alpha}) $,
\begin{eqnarray}
\hat{f_n} &=& \frac{1}{\chi_{n,\alpha}}\int_{-1}^1 \mathcal{L}_c^{(\alpha)}.\psi_{n,c}^{(\alpha)}(x) f(x) \omega_{\alpha}(x) dx =  \frac{1}{\chi_{n,\alpha}}\int_{-1}^1 \mathcal{L}_c^{(\alpha)}.f(x) \psi_{n,c}^{(\alpha)}(x)  \omega_{\alpha}(x) dx \nonumber \\
&=& ... = \frac{1}{(\chi_{n,\alpha})^r}\int_{-1}^1 \Big[\mathcal{L}_c^{(\alpha)}\Big]^r.f(x) \psi_{n,c}^{(\alpha)}(x)  \omega_{\alpha}(x) dx
\end{eqnarray}

Thus
\begin{eqnarray}
|\hat{f_n}|^2 &=& \frac{1}{\Big(\chi_{n}^{(\alpha)}\Big)^{2r}}|\Big<\Big[\mathcal{L}_c^{(\alpha)}\Big]^r.f,\psi_{n,c}^{(\alpha)}\Big>_{L^2(I,\omega_{\alpha})}|^2 \leq \frac{1}{\Big(\chi_{n}^{(\alpha)}\Big)^{2r}} \norm{\Big[\mathcal{L}_c^{(\alpha)}\Big]^rf}_{L^2(I,\omega_{\alpha})} \nonumber \\
&\leq & \frac{C}{\Big(\chi_{n}^{(\alpha)}\Big)^{2r}} \norm{f}^2_{r+2,\alpha}
\end{eqnarray}

In the following, we recall from \cite{Karoui-Souabni1} that for $c > 0$ a fixed positive real number, then, for all positive integers
$n,\; k$ such that $q=c^2/\chi^{\alpha}_{n}(c) <1$ and $ k(k+2\alpha+1)+C'_{\alpha}c^2\leq \chi_n^{\alpha}(c)$ , we have
\begin{eqnarray}

|\beta_k^n|&\leq& C_{\alpha}\left(\frac{2\sqrt{\chi_{n}^{\alpha}(c)}}{c} \right)^k |\mu_{n}^{\alpha}(c)|. \end{eqnarray}
With $C'_{\alpha}$ a constant depends only on $\alpha$, and $ {\displaystyle C_{\alpha}=\frac{2^{\alpha}(3/2)^{3/4}(3/2+2\alpha)^{3/4+\alpha}}{e^{2\alpha+3/2}}}$

